--region init

function CardProgressionFavorPopup:InitData()
    local parameters    = self.controller.Argument.parameters
    local playerCardId  = parameters.playerCardId
    local selectGoodsId   = parameters.selectGoodsId

    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo      = cardComponent:GetCardById(playerCardId)
    local cardId        = cardDojo.cardId

    ---@type RoleCardFavorableGiftVo
    local giftVo = cardConfMgr:GetRoleCardFavorableGiftVo(cardId)

    local favorGiftIds = parse_strings(checkString(cardDojo.favorGiftId), ",")
    local favorGiftId2Favor = {}
    for i, v in ipairs(favorGiftIds) do
        local goodsId = checkNumber(v)
        if goodsId > 0 then
            favorGiftId2Favor[goodsId] = true
        end
    end

    local goodsList = self:InitGoodsList(favorGiftId2Favor, giftVo)
    local index = 0
    if selectGoodsId then
        for i, v in ipairs(goodsList) do
            if v.vo.id == selectGoodsId then
                index = i
                break
            end
        end
    end
    
    self._goodsList = goodsList
    self._favorGiftId2Favor = favorGiftId2Favor
    self._selectIndex = index
    
end

function CardProgressionFavorPopup:InitGoodsList(favorGiftId2Favor, giftVo)
    ---@type CardFavorableGoodsVo[]
    local favorableGoodsVos = CfUtils.GetCf(AutoIds.IdSetting59, "CardFavorableGoodsVo", true)

    ---@type RestaurantCookingGoodsVo[]
    local cookingGoodsVo    = CfUtils.GetCf(AutoIds.IdSetting1013, "RestaurantCookingGoodsVo", true)
    local gifts = giftVo.gifts
    local goods = {}
    
    local FillGoods = function(vos, isDisableCheck)
        for i, vo in ipairs(vos) do
            local goodsId = vo.id
            local ownNum = GoodsUtils.GetThingNo(goodsId)
            local giftInfo = gifts[goodsId]
            local configIsFavor = giftInfo ~= nil
            local favorAddiNum = vo.gift
            if favorAddiNum > 0 and (ownNum > 0 or configIsFavor or isDisableCheck) then
                ---有服务端数据 并且 本地配表中配有该道具
                local isFavor = configIsFavor
                if giftInfo then
                    favorAddiNum = favorAddiNum + giftInfo.goodsNum
                end
                
                table.insert(goods, { vo = vo, ownNum = ownNum, isFavor = isFavor, favorAddiNum = favorAddiNum, configIsFavor = configIsFavor})
            end
        end
    end

    FillGoods(favorableGoodsVos, true)
    FillGoods(cookingGoodsVo)

    if next(goods) ~= nil then
        ---显示爱心的＞ 不显示爱心但是在喜好礼物表的＞好感度从大到小
        table.sort(goods, function (a, b)
            local aP = a.isFavor and 1 or 0
            local bP = b.isFavor and 1 or 0
            if aP ~= bP then
                return aP > bP
            end
            if a.favorAddiNum ~= b.favorAddiNum then
                return a.favorAddiNum > b.favorAddiNum
            end
            local aVo = a.vo
            local bVo = b.vo
            if aVo.quality ~= bVo.quality then
                return aVo.quality > bVo.quality
            end
            return aVo.id < bVo.id
        end)
        
    end
    return goods
end

function CardProgressionFavorPopup:InitAction()
    SetButtonAction(self.FontStyleButton, function()
        if self._selectIndex > 0 then
            
            KCookie.Set(CardProgressionConstants.CookieNames.FavorGoodsData, self._goodsList[self._selectIndex])
        end
        CfUtils.DialogBack()
    end)
    SetButtonAction(self.BtnClose, function()
        CfUtils.DialogBack()
    end)
    SetButtonAction(self.ClickClose, function()
        CfUtils.DialogBack()
    end)
end

