--region logic

function CardProgressionFavorPopup:FreshUI()
    local len = #self._goodsList
    ---@type SuperScrollView.LoopGridView
    local gridView = self.ScrollView
    local isShowList = len > 0
    KTool.SetActive(gridView.gameObject, isShowList)
    KTool.SetActive(self.Empty.gameObject, not isShowList)
    if isShowList then
        if gridView.IsListViewInit then
            GameUtils.ReloadData(gridView, len)
        else
            gridView:InitGridView(len, Bind(self, self.OnGetItemByIndex))
            if self._selectIndex > 0 then
                gridView:MovePanelToItemByIndex(self._selectIndex - 1)
            end
        end

    end
end

function CardProgressionFavorPopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CardProgressionConstants.NodeNames.Cell)
    local node = GetLuaBehaviour(cell.gameObject, CardProgressionConstants.EnvPath.CardProgressionFavorPopupCell)

    ---@type CardProgressionFavorPopupCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetCallback(Bind(self, self.OnClickGoodNodeAction))
    else
        nodeEnv = node.Env
    end

    if nodeEnv then
        local position = index + 1
        local goodsInfo = self._goodsList[position]
        nodeEnv:FreshUI(goodsInfo, position, position == self._selectIndex)
    end

    return cell
end

function CardProgressionFavorPopup:FreshCellSelectState(index, isSelect)
    local cell = self.ScrollView:GetShownItemByItemIndex(index - 1)
    if isNotNull(cell) then
        ---@type CardProgressionFavorPopupCell
        local env = CfUtils.GetLuaScr(cell.gameObject, CardProgressionConstants.EnvPath.CardProgressionFavorPopupCell)
        if isNotNull(env) then
            env:FreshSelectState(isSelect)
        end
    end
end

