--region handler

function CardProgressionFavorPopup:OnClickGoodNodeAction(index)
    if self._selectIndex == index then
        return
    end
    if self._selectIndex > 0 then
        self:FreshCellSelectState(self._selectIndex, false)
    end
    local goodsData = self._goodsList[index]
    ---@type CardFavorableGoodsVo | RestaurantCookingGoodsVo
    local vo = goodsData.vo
    self.TextDesc2.text = localize("每份【_name_】增加_num_好感度", {_name_ = vo.name, _num_ = goodsData.favorAddiNum})
    self:FreshCellSelectState(index, true)
    self._selectIndex = index
    
end

--endregion


return CardProgressionFavorPopup
 